class Movies:
    def __init__(self, path, limit):
        self.path, self.limit = path, limit

    @classmethod
    def default(cls):           # ФАБРИКА
        return cls('movies.csv', limit=1000)

m1 = Movies('movies.csv', 1000)  # помни параметры сам
m2 = Movies.default()            # фабрика помнит за тебя
